# Multiple aggregates
from sqlalchemy import func
session.query(
    Employee.dept_id,
    func.count(Employee.id),
    func.sum(Employee.salary),
    func.avg(Employee.salary),
    func.min(Employee.salary),
    func.max(Employee.salary)
).group_by(Employee.dept_id).all()

